SELECT s.id, s.account_id, s.collection_run_id, s.platform_type, s.balance, s.frozen_balance, s.total_requests, s.total_tokens, s.total_cost, s.total_actual_cost, s.metrics, s.platform_stats, s.collected_at FROM (VALUES
(#{accountId})
) AS a(account_id) CROSS JOIN LATERAL ( SELECT m.id, m.account_id, m.collection_run_id, m.platform_type, m.balance, m.frozen_balance, m.total_requests, m.total_tokens, m.total_cost, m.total_actual_cost, m.metrics, m.platform_stats, m.collected_at FROM account_usage_dashboard_snapshots m WHERE m.account_id = a.account_id ORDER BY m.collected_at DESC LIMIT 1 ) s

WITH ranked AS ( SELECT account_id, total_cost, row_number() OVER (PARTITION BY account_id ORDER BY collected_at ASC) AS first_rank, row_number() OVER (PARTITION BY account_id ORDER BY collected_at DESC) AS last_rank FROM account_usage_dashboard_snapshots WHERE account_id IN
#{accountId}
AND lower(platform_type) = 'newapi' AND total_cost IS NOT NULL AND collected_at >= #{from} AND collected_at <= #{to} ) SELECT account_id, max(total_cost) FILTER (WHERE first_rank = 1) AS first_cost, max(total_cost) FILTER (WHERE last_rank = 1) AS last_cost FROM ranked WHERE first_rank = 1 OR last_rank = 1 GROUP BY account_id

SELECT 
FROM account_usage_dashboard_snapshots
WHERE account_id = #{accountId}
AND collected_at >= #{from}
AND collected_at <= #{to}
ORDER BY collected_at ASC
LIMIT #{limit}

SELECT 
FROM account_usage_dashboard_snapshots
WHERE account_id IN

    #{accountId}

AND collected_at >= #{from}
AND collected_at <= #{to}
ORDER BY account_id ASC, collected_at ASC
